const clone=x=>structuredClone(x), pick=a=>a[Math.floor(Math.random()*a.length)], item=id=>CATALOG.find(c=>c.id===id);
export const physicalOffline=n=>n.active===false||!hasPower(n)||!!n.physical&&(!n.physical.on||n.physical.bootUntil>Date.now()||['dimm','controller','nic'].includes(n.physical.fault));
export const RACK_MAX_KG=1200;
